-- Carga de capas de Respuesta_T5610 (WGS84, EPSG:4326). Generado desde los .shp/.dbf originales.
-- Uso: psql -U postgres -d resiliencia -f cargar_capas.sql
CREATE EXTENSION IF NOT EXISTS postgis;
BEGIN;
DROP TABLE IF EXISTS public.fibra;
CREATE TABLE public.fibra (gid serial PRIMARY KEY, id text, geom geometry(MultiLineString,4326));
CREATE INDEX fibra_geom_gix ON public.fibra USING GIST (geom);
DROP TABLE IF EXISTS public.postacion;
CREATE TABLE public.postacion (gid serial PRIMARY KEY, id text, geom geometry(MultiLineString,4326));
CREATE INDEX postacion_geom_gix ON public.postacion USING GIST (geom);
DROP TABLE IF EXISTS public.caminos_sin_postacion;
CREATE TABLE public.caminos_sin_postacion (gid serial PRIMARY KEY, id text, geom geometry(MultiLineString,4326));
CREATE INDEX caminos_sin_postacion_geom_gix ON public.caminos_sin_postacion USING GIST (geom);
DROP TABLE IF EXISTS public.ferry;
CREATE TABLE public.ferry (gid serial PRIMARY KEY, id text, geom geometry(MultiLineString,4326));
CREATE INDEX ferry_geom_gix ON public.ferry USING GIST (geom);
COMMIT;
SELECT 'fibra' t,count(*) FROM public.fibra UNION ALL SELECT 'postacion',count(*) FROM public.postacion UNION ALL SELECT 'caminos_sin_postacion',count(*) FROM public.caminos_sin_postacion UNION ALL SELECT 'ferry',count(*) FROM public.ferry;
